$ErrorActionPreference='Stop'
$r=[ordered]@{scope='READ_ONLY_BEFORE_SINGLE_REPLACEMENT_CREATION';started_at_utc=[DateTime]::UtcNow.ToString('o')}
try {
$v=Get-VM -Id 'd5913cd7-aa99-4695-96b7-0d0135bad386'
$r.failed_vm=$v|Select-Object Id,Name,@{N='State';E={$_.State.ToString()}},Generation,Path
$r.failed_nic=@(Get-VMNetworkAdapter -VM $v|Select-Object Id,SwitchId,SwitchName,Connected,MacAddress)
$f=Get-VMFirmware -VM $v
$r.failed_firmware=[ordered]@{SecureBoot=$f.SecureBoot.ToString();SecureBootTemplate=$f.SecureBootTemplate}
$r.failed_worker_processes=@(Get-CimInstance Win32_Process -Filter "Name='vmwp.exe'"|Where-Object {$_.CommandLine -match 'd5913cd7-aa99-4695-96b7-0d0135bad386'}|Select-Object ProcessId,Name)
$r.failed_vhd_sha256=(Get-FileHash -Algorithm SHA256 'D:\LoaAlephPreparation\VM-PREP-SRC001-20260915-7a772f0\vm\executor.vhdx').Hash.ToLower()
$r.failed_image_sha256=(Get-FileHash -Algorithm SHA256 'D:\LoaAlephPreparation\VM-PREP-SRC001-20260915-7a772f0\images\ubuntu-24.04-minimal-cloudimg-amd64-20260905.img').Hash.ToLower()
$r.vms=@(Get-VM|Select-Object Id,Name,@{N='State';E={$_.State.ToString()}},Generation,Path)
$r.switch=Get-VMSwitch -Id 'c08cb7b8-9b3c-408e-8e30-5e16a3aeb444'|Select-Object Id,Name,@{N='SwitchType';E={$_.SwitchType.ToString()}}
$r.provisioning_host_ip=@(Get-NetIPAddress -InterfaceAlias 'vEthernet (Default Switch)' -AddressFamily IPv4|Select-Object IPAddress,PrefixLength,InterfaceIndex,InterfaceAlias)
$r.host_enhanced_session_capability=(Get-VMHost).EnableEnhancedSessionMode
if($v.State.ToString() -ne 'Off' -or @($r.failed_nic|Where-Object Connected).Count -ne 0 -or $r.failed_worker_processes.Count -ne 0){throw 'FAILED_VM_CONTAINMENT_MISMATCH'}
if($r.failed_vhd_sha256 -ne '5905c60cbc24b769af5dff0d79c21093ad523e652a6e8012c8b051b777bfefbb' -or $r.failed_image_sha256 -ne '46b0dbaffa6950a7da5ff2dc5ed34c46084610b3b6d1fae8f1ec2d7e953984a3'){throw 'FAILED_ARTIFACT_PIN_MISMATCH'}
if($r.vms.Count -ne 1 -or $r.vms[0].Id.ToString() -ne 'd5913cd7-aa99-4695-96b7-0d0135bad386'){throw 'UNEXPECTED_VM_INVENTORY'}
$r.result='PASS_FAILED_VM_PRESERVED_NO_REPLACEMENT_EXISTS'
} catch {$r.result='FAIL';$r.error=$_.Exception.Message}
$r.finished_at_utc=[DateTime]::UtcNow.ToString('o')
$r|ConvertTo-Json -Depth 8|Set-Content '\\wsl.localhost\Ubuntu\tmp\src001-replacement-image-gate-20260916\provisioning\precreate-host-gate.json' -Encoding UTF8
if($r.result -eq 'FAIL'){exit 1}

$ErrorActionPreference='Stop'
$r=[ordered]@{scope='SINGLE_REPLACEMENT_FIRST_BOOT_MECHANICAL_PROVISIONING_ONLY';vm_id='213ff077-356b-44a0-9032-df2ed0922b3a';started_at_utc=[DateTime]::UtcNow.ToString('o');boot_calls=0}
try {
$v=Get-VM -Id $r.vm_id;$f=Get-VMFirmware -VM $v
if($v.Name -ne 'SRC001-PREP-REPLACEMENT-fda0a0b' -or $v.State.ToString() -ne 'Off' -or $v.Generation -ne 2 -or $f.SecureBoot.ToString() -ne 'On' -or $f.SecureBootTemplate -ne 'MicrosoftUEFICertificateAuthority'){throw 'PREBOOT_CONFIGURATION_MISMATCH'}
$old=Get-VM -Id 'd5913cd7-aa99-4695-96b7-0d0135bad386';if($old.State.ToString() -ne 'Off' -or @(Get-VMNetworkAdapter -VM $old|Where-Object Connected).Count -ne 0){throw 'FAILED_VM_CONTAINMENT_MISMATCH'}
$marker='D:\LoaAlephPreparation\VM-PREP-SRC001-20260915-7a772f0\replacement-image-repair-20260916-fda0a0b\vm\first-boot-started.json'
if(Test-Path $marker){throw 'FIRST_BOOT_ALREADY_INITIATED_NO_RETRY'}
[ordered]@{vm_id=$r.vm_id;utc=[DateTime]::UtcNow.ToString('o')}|ConvertTo-Json|Set-Content $marker -Encoding UTF8
$r.boot_calls=1;Start-VM -VM $v
$r.vm=Get-VM -Id $r.vm_id|Select-Object Id,Name,@{N='State';E={$_.State.ToString()}},Uptime
$r.nic=@(Get-VMNetworkAdapter -VMName $v.Name|Select-Object Id,MacAddress,SwitchId,SwitchName,Connected)
$r.result='FIRST_BOOT_STARTED_GUEST_BOOT_OUTCOME_PENDING'
} catch {$r.result='FAIL_STOP';$r.error=$_.Exception.Message}
$r.finished_at_utc=[DateTime]::UtcNow.ToString('o');$r|ConvertTo-Json -Depth 8|Set-Content '\\wsl.localhost\Ubuntu\tmp\src001-replacement-image-gate-20260916\provisioning\first-boot-start.json' -Encoding UTF8
if($r.result -eq 'FAIL_STOP'){exit 1}

$ErrorActionPreference='Stop'
$r=[ordered]@{scope='REPLACEMENT_FAILURE_CONTAINMENT_NO_RETRY';started_at_utc=[DateTime]::UtcNow.ToString('o');vm_id='213ff077-356b-44a0-9032-df2ed0922b3a';boot_calls=0;old_vm_mutations=0}
try {
$v=Get-VM -Id $r.vm_id
$r.before=$v|Select-Object Id,Name,@{N='State';E={$_.State.ToString()}},Uptime
if($v.Name -ne 'SRC001-PREP-REPLACEMENT-fda0a0b' -or $v.State.ToString() -ne 'Off'){throw 'REPLACEMENT_STATE_REQUIRES_SEPARATE_CONTAINMENT_REVIEW'}
$r.nic_before=@(Get-VMNetworkAdapter -VM $v|Select-Object Id,MacAddress,SwitchId,SwitchName,Connected)
Get-VMNetworkAdapter -VM $v|Disconnect-VMNetworkAdapter
$r.nic_after=@(Get-VMNetworkAdapter -VM $v|Select-Object Id,MacAddress,SwitchId,SwitchName,Connected)
$r.failed_vm=Get-VM -Id 'd5913cd7-aa99-4695-96b7-0d0135bad386'|Select-Object Id,Name,@{N='State';E={$_.State.ToString()}},Generation,Path
$r.failed_nic=@(Get-VMNetworkAdapter -VMName 'SRC001-PREP-7a772f0'|Select-Object Id,MacAddress,SwitchId,SwitchName,Connected)
$r.replacement_vm=Get-VM -Id $r.vm_id|Select-Object Id,Name,@{N='State';E={$_.State.ToString()}},Generation,Version,Path,ProcessorCount,MemoryStartup,DynamicMemoryEnabled,Uptime
$f=Get-VMFirmware -VM $v;$r.firmware=[ordered]@{SecureBoot=$f.SecureBoot.ToString();SecureBootTemplate=$f.SecureBootTemplate;BootOrder=@($f.BootOrder|Select-Object BootType,Description,FirmwarePath)}
$r.disks=@(Get-VMHardDiskDrive -VM $v|Select-Object Path,@{N='ControllerType';E={$_.ControllerType.ToString()}},ControllerNumber,ControllerLocation)
$r.vhd=Get-VHD -Path $r.disks[0].Path|Select-Object Path,Size,FileSize,ParentPath,Attached,DiskIdentifier
$r.vhd_sha256=(Get-FileHash -Algorithm SHA256 $r.disks[0].Path).Hash.ToLower()
$r.failed_vhd_sha256=(Get-FileHash -Algorithm SHA256 'D:\LoaAlephPreparation\VM-PREP-SRC001-20260915-7a772f0\vm\executor.vhdx').Hash.ToLower()
$r.failed_image_sha256=(Get-FileHash -Algorithm SHA256 'D:\LoaAlephPreparation\VM-PREP-SRC001-20260915-7a772f0\images\ubuntu-24.04-minimal-cloudimg-amd64-20260905.img').Hash.ToLower()
$r.worker_processes=@(Get-CimInstance Win32_Process -Filter "Name='vmwp.exe'"|Where-Object {$_.CommandLine -match '(213ff077-356b-44a0-9032-df2ed0922b3a|d5913cd7-aa99-4695-96b7-0d0135bad386)'}|Select-Object ProcessId,Name,CommandLine)
$r.vms=@(Get-VM|Select-Object Id,Name,@{N='State';E={$_.State.ToString()}},Generation)
$r.host_memory=Get-CimInstance Win32_OperatingSystem|Select-Object TotalVisibleMemorySize,FreePhysicalMemory,TotalVirtualMemorySize,FreeVirtualMemory
$r.dvd=@(Get-VMDvdDrive -VM $v|Select-Object Path,ControllerNumber,ControllerLocation)
$r.integration=@(Get-VMIntegrationService -VM $v|Select-Object Name,Enabled)
$r.retention='Both VMs/configurations/disks retained. Only replacement NIC disconnected; replacement seed remains attached to OFF VM as evidence. No retry, reboot, memory change, old-VM mutation or image modification.'
if($r.failed_vm.State -ne 'Off' -or @($r.failed_nic|Where-Object Connected).Count -ne 0 -or @($r.nic_after|Where-Object Connected).Count -ne 0 -or $r.worker_processes.Count -ne 0){throw 'CONTAINMENT_READBACK_FAILED'}
if($r.failed_vhd_sha256 -ne '5905c60cbc24b769af5dff0d79c21093ad523e652a6e8012c8b051b777bfefbb' -or $r.failed_image_sha256 -ne '46b0dbaffa6950a7da5ff2dc5ed34c46084610b3b6d1fae8f1ec2d7e953984a3'){throw 'FAILED_ARTIFACT_PRESERVATION_FAILED'}
$r.result='PASS_BOTH_OFF_BOTH_NICS_DISCONNECTED_FAILED_ARTIFACTS_UNCHANGED'
} catch {$r.result='FAIL';$r.error=$_.Exception.Message}
$r.finished_at_utc=[DateTime]::UtcNow.ToString('o');$r|ConvertTo-Json -Depth 10|Set-Content '\\wsl.localhost\Ubuntu\tmp\src001-replacement-image-gate-20260916\provisioning\replacement-final-containment.json' -Encoding UTF8
if($r.result -eq 'FAIL'){exit 1}
